15	// DEVDESK-580: the catalog walk replayed against the pages NX-03 measured. DevDesk
16	// asks for n=1000, so on the six names of the bench it never pages; these tests
17	// call the walker with a page size of 1 or 2 to follow the Link headers Nexus
18	// really sent, with the last name escaped ("last=shared%2Fbase"). They lock the
19	// measurement: they pass as soon as the fixtures are there, and fail when a page
20	// of the measured chain is missing.
21	
22	const (
23		groupHost = "127.0.0.1:30482" // the group connector
24		pathHost  = "127.0.0.1:30481" // the HTTP port, repositories by path
25	)
26	
27	// pageFakeTB captures the errors of a fake so that a test can expect them. It
28	// embeds the real T for everything else (Cleanup stops the fake servers).
29	type pageFakeTB struct {
30		testing.TB
31		errs []string
32	}
33	
34	func (f *pageFakeTB) Helper() {}
35	
36	func (f *pageFakeTB) Errorf(format string, args ...any) {
37		f.errs = append(f.errs, fmt.Sprintf(format, args...))
38	}
39	
40	// measuredPages loads the named catalog fixtures (without the "--admin" suffix),
41	// in the order given, and fails the test on a name that is not embedded.
42	func measuredPages(t *testing.T, names ...string) []nexusfixture.Fixture {
43		t.Helper()
44		all, err := nexusfixture.Load("catalog")
45		if err != nil {
46			t.Fatalf("Load(catalog): %v", err)
47		}
48		var out []nexusfixture.Fixture
49		for _, name := range names {
50			i := slices.IndexFunc(all, func(f nexusfixture.Fixture) bool { return f.Name == name+"--admin" })
51			if i < 0 {
52				t.Fatalf("the embedded catalog has no fixture %s--admin", name)
53			}
54			out = append(out, all[i])
55		}
56		return out
57	}
58	
59	func pageNames(prefix string, n int) []string {
60		var names []string
61		for k := range n {
62			names = append(names, fmt.Sprintf("%s-p%d", prefix, k))
63		}
64		return names
65	}
66	
67	func walk(t *testing.T, base, prefix string, pageSize int) ([]string, bool, error) {
68		t.Helper()
69		return oci.ListCatalogUnderContext(context.Background(), base, prefix,
70			fakenexus.User(nexusfixture.Admin), fakenexus.Password, 10, pageSize)
71	}
72	
73	func requireHits(t *testing.T, fake *fakenexus.Server, names []string, want int) {
74		t.Helper()
75		total := 0
76		for _, name := range names {
77			got := fake.Hits(name + "--admin")
78			total += got
79			if got != want {
80				t.Errorf("Hits(%s--admin) = %d, want %d", name, got, want)
81			}
82		}
83		if total != want*len(names) {
84			t.Errorf("%d requests in all, want %d", total, want*len(names))
85		}
86	}
