88	func TestCatalogWalkFollowsEveryMeasuredPage(t *testing.T) {
89		pages := pageNames("page-group-n1", 6)
90	
91		t.Run("six pages of one name", func(t *testing.T) {
92			fake := fakenexus.New(t, measuredPages(t, pages...)...)
93			names, truncated, err := walk(t, fake.URL(groupHost), "", 1)
94			if err != nil {
95				t.Fatalf("ListCatalogUnderContext: %v", err)
96			}
97			want := []string{"api", "mirror/cached", "mirror/uncached", "shared/base", "team/api", "tools/cli"}
98			if !slices.Equal(names, want) {
99				t.Errorf("names = %v, want %v (the order Nexus sent)", names, want)
100			}
101			if truncated {
102				t.Error("truncated = true, want false: the last page has no Link")
103			}
104			requireHits(t, fake, pages, 1)
105		})
106	
107		t.Run("a lost page", func(t *testing.T) {
108			lost := slices.DeleteFunc(slices.Clone(pages), func(n string) bool { return n == "page-group-n1-p3" })
109			spy := &pageFakeTB{TB: t}
110			fake := fakenexus.New(spy, measuredPages(t, lost...)...)
111			names, _, err := walk(t, fake.URL(groupHost), "", 1)
112			var statusErr *oci.StatusError
113			if !errors.As(err, &statusErr) || statusErr.Code != 501 {
114				t.Fatalf("err = %v, want a *oci.StatusError 501 for the page no fixture answers", err)
115			}
116			if len(names) != 0 {
117				t.Errorf("names = %v, want none on an error", names)
118			}
119			if len(spy.errs) != 1 {
120				t.Errorf("the fake reported %d unrecorded request(s) %q, want exactly the one for page 3", len(spy.errs), spy.errs)
121			}
122		})
123	}
