125	// Nexus pages a group inconsistently (NX-03): a name comes back on two pages.
126	// The walker does not deduplicate at this level; the test pins what was sent.
127	func TestCatalogWalkKeepsTheMeasuredGroupN2Answer(t *testing.T) {
128		pages := pageNames("page-group-n2", 5)
129		fake := fakenexus.New(t, measuredPages(t, pages...)...)
130		names, truncated, err := walk(t, fake.URL(groupHost), "", 2)
131		if err != nil {
132			t.Fatalf("ListCatalogUnderContext: %v", err)
133		}
134		want := []string{
135			"api", "mirror/cached",
136			"mirror/uncached", "shared/base",
137			"team/api", "tools/cli",
138			"shared/base", "team/api",
139			"tools/cli",
140		}
141		if len(want) != 9 {
142			t.Fatalf("test bug: %d names", len(want))
143		}
144		if !slices.Equal(names, want) {
145			t.Errorf("names = %v, want %v", names, want)
146		}
147		if truncated {
148			t.Error("truncated = true, want false")
149		}
150		for _, dup := range []string{"shared/base", "team/api", "tools/cli"} {
151			if got := count(names, dup); got != 2 {
152				t.Errorf("%s appears %d times, want 2 (Nexus sent it twice)", dup, got)
153			}
154		}
155		requireHits(t, fake, pages, 1)
156	}
157	
158	func count(list []string, s string) int {
159		n := 0
160		for _, x := range list {
161			if x == s {
162				n++
163			}
164		}
165		return n
166	}
