168	// A member read by its path keeps its Link on that path: the measured next link
169	// of docker-hosted and docker-proxy stays under /v2/<repository>/_catalog.
170	func TestCatalogWalkUnderAMemberFollowsItsMeasuredPages(t *testing.T) {
171		tests := []struct {
172			prefix string
173			pages  []string
174			want   []string
175		}{
176			{
177				prefix: "docker-hosted",
178				pages:  pageNames("page-hosted-n2", 2),
179				want:   []string{"api", "shared/base", "team/api", "tools/cli"},
180			},
181			{
182				prefix: "docker-proxy",
183				pages:  pageNames("page-proxy-n2", 2),
184				want:   []string{"mirror/cached", "mirror/uncached", "shared/base"},
185			},
186		}
187		for _, tt := range tests {
188			t.Run(tt.prefix, func(t *testing.T) {
189				fake := fakenexus.New(t, measuredPages(t, tt.pages...)...)
190				names, truncated, err := walk(t, fake.URL(pathHost), tt.prefix, 2)
191				if err != nil {
192					t.Fatalf("ListCatalogUnderContext: %v", err)
193				}
194				if !slices.Equal(names, tt.want) {
195					t.Errorf("names = %v, want %v", names, tt.want)
196				}
197				if truncated {
198					t.Error("truncated = true, want false: the walk left the member's path or stopped early")
199				}
200				requireHits(t, fake, tt.pages, 1)

