41	// errEmptyReply, errNoRepositoryType and errNoGroupDocument mark a 200 reply
42	// that is not a repository (or group) document. All fail the discovery: reading
43	// any of them as "not a group" would be cached (D23) and erase the members last
44	// known.
45	var (
46		errEmptyReply       = errors.New("empty reply")
47		errNoRepositoryType = errors.New("reply names no repository type")
48		errNoGroupDocument  = errors.New("reply is not a group document")
49	)
