65		if !ok {
66			t.Fatalf("fixture %s is missing from the catalog campaign", name)
67		}
68		if len(f.Exchanges) != 1 {
69			t.Fatalf("fixture %s has %d exchanges, want 1", name, len(f.Exchanges))
70		}
71		return f.Exchanges[0]
72	}
