74	// The premises every verdict below rests on, read from the fixtures.
75	func TestMeasuredRESTAnswersHoldThePremises(t *testing.T) {
76		fixtures := restFixtures(t)
77	
78		// Criterion 3: the generic endpoint answers 200 to all three accounts, names
79		// the type, and carries no memberNames anywhere (so step 2 of DetectGroup is
80		// always reached for a group).
81		for _, tc := range []struct{ repo, typ string }{{restGroup, "group"}, {restHosted, "hosted"}, {restProxy, "proxy"}} {
82			for _, id := range restIdentities {
83				ex := restExchange(t, fixtures, genericFixture(tc.repo, id))
84				if ex.Status != http.StatusOK {
85					t.Errorf("%s generic as %s: status %d, want 200", tc.repo, id, ex.Status)
86				}
87				var doc struct {
88					Type  string `json:"type"`
89					Group any    `json:"group"`
90					Attrs struct {
91						Group any `json:"group"`
92					} `json:"attributes"`
93				}
94				if err := json.Unmarshal(ex.Body, &doc); err != nil {
95					t.Fatalf("%s generic as %s: %v", tc.repo, id, err)
96				}
97				if doc.Type != tc.typ {
98					t.Errorf("%s generic as %s: type %q, want %q", tc.repo, id, doc.Type, tc.typ)
99				}
100				if doc.Group != nil || doc.Attrs.Group != nil {
101					t.Errorf("%s generic as %s carries a group document: DetectGroup would stop at step 1", tc.repo, id)
102				}
103			}
104		}
105	
106		// The detailed endpoint of the group: 200 with the members for admin, 403
107		// with no body for anonymous, and 404 "Repository not found" (not 403) for the
108		// pull account (C1 of the DEVDESK-511 plan, decided by the user).
109		admin := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Admin))
110		if admin.Status != http.StatusOK {
111			t.Errorf("detailed as admin: status %d, want 200", admin.Status)
112		}
113		if got := memberNamesOf(t, admin.Body); !reflect.DeepEqual(got, []string{restHosted, restProxy}) {
114			t.Errorf("detailed as admin: memberNames %v, want [%s %s]", got, restHosted, restProxy)
115		}
116		anon := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Anonymous))
117		if anon.Status != http.StatusForbidden || len(anon.Body) != 0 {
118			t.Errorf("detailed as anonymous: %d %q, want 403 with no body", anon.Status, anon.Body)
119		}
120		pull := restExchange(t, fixtures, detailedFixture(restGroup, nexusfixture.Pull))
121		if pull.Status != http.StatusNotFound || !strings.Contains(string(pull.Body), "Repository not found") {
122			t.Errorf("detailed as pull: %d %q, want 404 \"Repository not found\"", pull.Status, pull.Body)
123		}
124		// DEVDESK-578: the body is what tells this 404 from any other one.
125		if !isRepositoryNotFound(pull.Body) {
126			t.Errorf("isRepositoryNotFound(%q) = false, want true for the measured pull body", pull.Body)
127		}
128	}
