130	func memberNamesOf(t *testing.T, body []byte) []string {
131		t.Helper()
132		var doc struct {
133			Group struct {
134				MemberNames []string `json:"memberNames"`
135			} `json:"group"`
136		}
137		if err := json.Unmarshal(body, &doc); err != nil {
138			t.Fatalf("reading memberNames: %v", err)
139		}
140		return doc.Group.MemberNames
