153	// wantHits fails unless each named fixture answered exactly the given number of
154	// requests and nothing else answered any.
155	func wantHits(t *testing.T, s *fakenexus.Server, fixtures map[string]nexusfixture.Fixture, want map[string]int) {
156		t.Helper()
157		total, wantTotal := 0, 0
158		for name := range fixtures {
159			total += s.Hits(name)
160		}
161		for name, n := range want {
162			wantTotal += n
163			if got := s.Hits(name); got != n {
164				t.Errorf("Hits(%s) = %d, want %d", name, got, n)
165			}
166		}
167		if total != wantTotal {
168			t.Errorf("%d requests answered in total, want %d", total, wantTotal)
169		}
170	}
