181	func TestDetectGroupOnMeasuredNexusAnswers(t *testing.T) {
182		fixtures := restFixtures(t)
183		all := make([]nexusfixture.Fixture, 0, len(fixtures))
184		for _, f := range fixtures {
185			all = append(all, f)
186		}
187	
188		t.Run("group as admin lists its members", func(t *testing.T) {
189			s := fakenexus.New(t, all...)
190			id := nexusfixture.Admin
191	
192			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
193	
194			if err != nil {
195				t.Fatalf("err = %v, want nil", err)
196			}
197			if want := measuredMembers(s); !reflect.DeepEqual(members, want) {
198				t.Errorf("members = %+v, want %+v", members, want)
199			}
200			wantHits(t, s, fixtures, map[string]int{genericFixture(restGroup, id): 1, detailedFixture(restGroup, id): 1})
201		})
202	
203		t.Run("group as anonymous is refused, 403", func(t *testing.T) {
204			s := fakenexus.New(t, all...)
205			id := nexusfixture.Anonymous
206	
207			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
208	
209			wantRefused(t, members, err, http.StatusForbidden, true)
210			// No credential, so no anonymous retry: one request on the detailed endpoint.
211			wantHits(t, s, fixtures, map[string]int{genericFixture(restGroup, id): 1, detailedFixture(restGroup, id): 1})
212		})
213	
214		// C1 (DEVDESK-511 plan, decided by the user): the pull account does not get
215		// the 403 that D161 (NX-07) assumed on the detailed endpoint, it gets 404
216		// "Repository not found" (rest-repositories-group-docker-group--pull). That is
217		// Nexus hiding the endpoint from an account without nx-repository-admin, not a
218		// repository that is missing (the generic endpoint just said it is a group),
219		// so since DEVDESK-578 (NX-07b) it is a refusal like the 403: the UI can say
220		// "denied" instead of "unreachable". Only this 404 body qualifies; every other
221		// 404 stays a failed discovery (see TestNexusMembers404*).
222		t.Run("group as the pull account is refused, 404 Repository not found", func(t *testing.T) {
223			s := fakenexus.New(t, all...)
224			id := nexusfixture.Pull
