226			members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, restGroup, id))
227	
228			wantRefused(t, members, err, http.StatusNotFound, false)
229			if strings.Contains(err.Error(), fakenexus.Password) {
230				t.Errorf("error leaks the password: %v", err)
231			}
232			// The account's 404, then D156's anonymous retry, which the anonymous
233			// recording answers with its 403: the first attempt decides, so the 403 is
234			// not what the error reports.
235			wantHits(t, s, fixtures, map[string]int{
236				genericFixture(restGroup, id):                      1,
237				detailedFixture(restGroup, id):                     1,
238				detailedFixture(restGroup, nexusfixture.Anonymous): 1,
239			})
240		})
241	
242		// A hosted or a proxy repository says what it is on the generic endpoint, and
243		// that is the end of it: not a group, no detailed request.
244		for _, repo := range []string{restHosted, restProxy} {
245			for _, id := range restIdentities {
246				t.Run(repo+" as "+string(id)+" is not a group", func(t *testing.T) {
247					s := fakenexus.New(t, all...)
248	
249					members, err := (&NexusDetector{}).DetectGroup(context.Background(), restInfo(s, repo, id))
250	
251					if err != nil || members != nil {
252						t.Fatalf("DetectGroup = (%v, %v), want (nil, nil): not a group is a settled answer", members, err)
253					}
254					wantHits(t, s, fixtures, map[string]int{genericFixture(repo, id): 1})
255				})
256			}
257		}
