18	func init() {
19		Register(&NexusDetector{})
20	}
21	
22	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
23	// Two URL formats are supported:
24	//  1. Path-based:   https://nexus.example.com/repository/docker-group
25	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
26	//
27	// Which one applies is read from the URL. Whether this detector runs at all is
28	// not: that is the declared provider's decision (§3.8, decision F).
29	type NexusDetector struct{}
30	
31	// maxNexusResponse bounds what one Nexus reply may take in memory. The replies
32	// are small JSON documents (a repository and the names of its members); the
33	// figure follows the reasoning of the catalog page cap and is not measured.
34	const maxNexusResponse = 1 << 20
35	
36	// maxNexusErrorBody bounds how much of a 404 body is read to tell Nexus's own
37	// "Repository not found" from any other 404. An assumption: the measured body is
38	// about 50 bytes. A longer one is not trusted and the 404 stays a plain status.
39	const maxNexusErrorBody = 4 << 10
40	
41	// errEmptyReply, errNoRepositoryType and errNoGroupDocument mark a 200 reply
42	// that is not a repository (or group) document. All fail the discovery: reading
43	// any of them as "not a group" would be cached (D23) and erase the members last
44	// known.
45	var (
46		errEmptyReply       = errors.New("empty reply")
47		errNoRepositoryType = errors.New("reply names no repository type")
48		errNoGroupDocument  = errors.New("reply is not a group document")
49	)
50	
51	// nexusHTTPClient refuses a redirect to another origin, so the account of the
52	// registry is never sent to a host it was not given for.
53	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
54	
55	// Provider returns the provider this detector serves.
56	func (n *NexusDetector) Provider() string { return ProviderNexus }
57	
58	// repositoryNotFoundError is a 404 from the management API whose body is Nexus's
59	// own "Repository not found". Its text and its cause are the status error's,
60	// never the body.
61	type repositoryNotFoundError struct{ status *oci.StatusError }
62	
63	func (e *repositoryNotFoundError) Error() string { return e.status.Error() }
64	func (e *repositoryNotFoundError) Unwrap() error { return e.status }
65	
66	// isRepositoryNotFound reports whether body is the JSON object Nexus sends for
67	// "Repository not found": a `message` string that equals it once the quotes inside
68	// and the whitespace around are removed, case ignored. Anything else is false.
69	func isRepositoryNotFound(body []byte) bool {
70		var doc struct {
71			Message any `json:"message"`
72		}
73		if err := json.Unmarshal(body, &doc); err != nil {
74			return false
75		}
76		msg, ok := doc.Message.(string)
77		if !ok {
78			return false
79		}
80		msg = strings.TrimSpace(strings.ReplaceAll(msg, `"`, ""))
81		return strings.EqualFold(msg, "Repository not found")
82	}
83	
84	// DetectGroup calls the Nexus REST API to determine whether the registry points
85	// to a group repository and, if so, returns its member repositories.
86	//
87	// Returns nil, nil when the manager answered and the repository is not a group,
88	// a non-nil empty list for a group it listed with no member, and an error when it
89	// could not be asked or refused to list the members (a *MembersRefusedError,
90	// errors.Is ErrMembersRefused). Those are not the same thing: the caller caches
91	// the settled answers and must not cache an error, or one unreachable minute (or
92	// one refused account) erases what was last known (D23).
93	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
94		// Resolve which URL to use for the Nexus API call.
95		apiBase := info.ManagementURL
96		if apiBase == "" {
97			apiBase = info.URL
98		}
99	
100		host, repoName, err := parseNexusURL(apiBase)
101		if err != nil {
102			// Not an error: a URL that is not a Nexus repository path is a settled
103			// answer, not a failure to reach one.
104			// The cause only: a URL that does not parse may hold a password, and
105			// url.Error repeats it whole.
106			var ue *url.Error
107			if errors.As(err, &ue) {
108				err = ue.Err
109			}
110			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
111			return nil, nil
112		}
113	
114		hasAuth := info.Username != "" && info.Password != ""
115		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
116	
117		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
118		// and may already include memberNames in the attributes field (no admin privilege needed).
119		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
120		if err != nil {
121			return nil, err
122		}
123		if repoType != "group" {
124			return nil, nil
125		}
126	
127		if len(members) > 0 {
128			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
129			return members, nil
130		}
131	
132		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
133		// but returns memberNames reliably on Nexus instances that support it.
134		members, err = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
135		if err != nil {
136			return nil, err
137		}
138		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
139		return members, nil
140	}
141	
142	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
143	// Returns type, format and any memberNames found in attributes, or an error when
144	// the manager could not be asked.
145	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
146	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
147		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
148		body, err := n.nexusGET(ctx, endpoint, info)
149		if err != nil {
150			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
151			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
152		}
153		if len(bytes.TrimSpace(body)) == 0 {
154			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
155			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
156		}
157		var result struct {
158			Type   string `json:"type"`
159			Format string `json:"format"`
160			Group  struct {
161				MemberNames []string `json:"memberNames"`
162			} `json:"group"`
163			Attributes struct {
164				Group struct {
165					MemberNames []string `json:"memberNames"`
166				} `json:"group"`
167			} `json:"attributes"`
168		}
169		if err := json.Unmarshal(body, &result); err != nil {
170			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
171			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
172		}
173		if result.Type == "" {
174			// Valid JSON that is not a repository document: `{}`, `null`.
175			log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
176			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
177		}
178		log.Printf("INFO [registrymgr/nexus] meta %q: type=%q format=%q", repoName, result.Type, result.Format)
179	
180		// Collect memberNames from whichever field Nexus populated.
181		rawNames := result.Group.MemberNames
182		if len(rawNames) == 0 {
183			rawNames = result.Attributes.Group.MemberNames
184		}
185		members = memberList(info.URL, rawNames)
186		return result.Type, result.Format, members, nil
187	}
188	
189	// fetchGroupMembers calls the format-specific group endpoint which reliably
190	// includes memberNames: GET /v1/repositories/{format}/group/{name}
191	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
192	//
193	// It returns a settled listing (non-nil, possibly empty) or an error, never a
194	// silent "no members": a 401, a 403 or Nexus's 404 Repository not found is a
195	// *MembersRefusedError, anything else that goes wrong is returned as it is. The
196	// caller caches the first and must not cache the second (D23).
197	//
198	// The first attempt decides. The anonymous retry (D156) only changes the outcome
199	// by succeeding: whatever it gets otherwise, the account was refused and that is
200	// the actionable fact.
201	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) ([]GroupMember, error) {
202		if format == "" {
203			format = "docker"
204		}
205		// The format comes from the server: it stays one path segment.
206		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, url.PathEscape(format), repoName)
207		body, err := n.nexusGET(ctx, endpoint, info)
208		if err != nil {
209			firstErr := err
210			// When auth is present but the request fails, retry anonymously.
211			// Some Nexus instances allow anonymous read of the group admin endpoint.
212			// A refused redirect to another origin is not such a failure: the
213			// detection stops there (DEVDESK-412), no silent anonymous retry.
214			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
215				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
216				body, err = n.nexusGET(ctx, endpoint, anonInfo)
217				if err != nil {
218					log.Printf("INFO [registrymgr/nexus] anonymous retry for %q failed: %v", repoName, err)
219				}
220			}
221			if err != nil {
222				return nil, membersFailure(host, repoName, endpoint, firstErr, info.Username != "" && info.Password != "")
223			}
224		}
225		names, err := parseGroupMembers(body)
226		if err != nil {
227			log.Printf("INFO [registrymgr/nexus] members %q: %v", repoName, err)
228			return nil, fmt.Errorf("reading the members of group %q: %w", repoName, err)
229		}
230		return memberList(info.URL, names), nil
231	}
232	
233	// membersFailure logs and types the failure of the first attempt on the format
234	// endpoint: a refusal when the manager refused the account, the error itself
235	// otherwise. The returned error holds the group and the status, never the URL.
236	func membersFailure(host, repoName, endpoint string, err error, hasAuth bool) error {
237		if status, ok := refusedStatus(err); ok {
238			log.Printf("INFO [registrymgr/nexus] members refused %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
239			// The cause is the status error itself, so the refusal never carries a
240			// repositoryNotFoundError nor anything of the body.
241			// refusedStatus found one, so errors.As should not fail; if it does, the
242			// cause stays nil rather than an interface holding a nil pointer.
243			var cause error
244			var statusErr *oci.StatusError
245			if errors.As(err, &statusErr) {
246				cause = statusErr
247			}
248			return &MembersRefusedError{Group: repoName, Status: status, Anonymous: !hasAuth, Cause: cause}
249		}
250		if errors.Is(err, oci.ErrOffOriginRedirect) {
251			// The advice above is for an account Nexus refused, not for this.
252			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
253		} else {
254			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v", endpoint, err)
255		}
256		return fmt.Errorf("reading the members of group %q: %w", repoName, err)
257	}
258	
259	// parseGroupMembers reads the member names of a format-endpoint reply. A document
260	// is a `group` object carrying a `memberNames` key, an empty list included: an
261	// empty body, `null`, `{}` or a group without the key is not one, and reading it
262	// as "no members" would be cached over what was last known.
263	func parseGroupMembers(body []byte) ([]string, error) {
264		if len(bytes.TrimSpace(body)) == 0 {
265			return nil, errEmptyReply
266		}
267		var doc struct {
268			Group *struct {
269				MemberNames []string `json:"memberNames"`
270			} `json:"group"`
271		}
272		if err := json.Unmarshal(body, &doc); err != nil {
273			return nil, fmt.Errorf("parsing the reply: %w", err)
274		}
275		if doc.Group == nil || doc.Group.MemberNames == nil {
276			return nil, errNoGroupDocument
277		}
278		return doc.Group.MemberNames, nil
279	}
280	
281	// refusedStatus reports the status of a management API refusal: 401 or 403 from
282	// the manager itself, not from anything in front of it, or the 404 Nexus answers
283	// an account without nx-repository-admin (see repositoryNotFoundError).
284	func refusedStatus(err error) (int, bool) {
285		var nf *repositoryNotFoundError
286		if errors.As(err, &nf) {
287			return http.StatusNotFound, true
288		}
289		var se *oci.StatusError
290		if !errors.As(err, &se) || se.Source != oci.SourceManagementAPI {
291			return 0, false
292		}
293		if se.Code != http.StatusUnauthorized && se.Code != http.StatusForbidden {
294			return 0, false
295		}
296		return se.Code, true
297	}
298	
299	// memberList turns the names a group declares into addresses.
300	func memberList(dockerURL string, names []string) []GroupMember {
301		members := make([]GroupMember, 0, len(names))
302		for _, name := range names {
303			url, prefix := memberAddress(dockerURL, name)
304			members = append(members, GroupMember{
305				Alias:      cleanMemberAlias(name),
306				URL:        url,
307				RepoPrefix: prefix,
308			})
309		}
310		return members
311	}
312	
313	// memberAddress decides how one member of a group is reached, from the URL the
314	// group itself is pulled from.
315	//
316	// A group written as a path prefix — `host/repository/<group>` — is an instance
317	// serving its Docker repositories that way, so its members are reached the same
318	// way: the host, with the member's name in front of the repository. That pair is
319	// consistent by construction, because browse and pull build the same path from
320	// it.
321	//
322	// Anything else is a connector of the group's own — a dedicated port, a
323	// subdomain — and says nothing about a member. Which of those a repository
324	// answers on is a setting on that repository (`docker.httpPort`,
325	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
326	// refused to an ordinary pull account. So nothing is claimed: the member is
327	// offered at the group's own address with no prefix, which browses to nothing
328	// visibly rather than pulling to nothing plausibly (§3.18).
329	func memberAddress(dockerURL, memberName string) (url, prefix string) {
330		host, _, err := parseNexusURL(dockerURL)
331		if err != nil {
332			return dockerURL, ""
333		}
334		// parseNexusURL supplies https:// for a URL written without a scheme. The
335		// group's own spelling is what the rest of the application is keyed on, so
336		// it is kept rather than normalised here.
337		if !strings.Contains(strings.ToLower(dockerURL), "://") {
338			host = strings.TrimPrefix(host, "https://")
339		}
340		return host, memberName
341	}
342	
343	// nexusGET performs an authenticated GET and returns the response body. A status
344	// other than 200 is a *oci.StatusError from the management API: the code only, no
345	// status line, body or header. A 404 whose body is Nexus's own "Repository not
346	// found" is a *repositoryNotFoundError, which wraps that same status error. A
347	// context error stays a context error.
348	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
349		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
350		if err != nil {
351			return nil, err
352		}
353		if info.Username != "" && info.Password != "" {
354			req.SetBasicAuth(info.Username, info.Password)
355		}
356		resp, err := nexusHTTPClient.Do(req)
357		if err != nil {
358			// A refused redirect comes back without the URL it pointed to, which
359			// may be signed.
360			return nil, oci.StripRedirectTarget(err)
361		}
362		defer func() { _ = resp.Body.Close() }()
363		if resp.StatusCode != http.StatusOK {
364			status := &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceManagementAPI}
365			if resp.StatusCode != http.StatusNotFound {
366				return nil, status
367			}
368			errBody, err := oci.ReadAllLimited(resp.Body, maxNexusErrorBody)
369			if err != nil {
370				if ctxErr := ctx.Err(); ctxErr != nil {
371					return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
372				}
373				return nil, status
374			}
375			if isRepositoryNotFound(errBody) {
376				return nil, &repositoryNotFoundError{status: status}
377			}
378			return nil, status
379		}
380		body, err := oci.ReadAllLimited(resp.Body, maxNexusResponse)
381		if err != nil {
382			// Which error net/http gives a body cut by a cancel varies: report the
383			// context's own.
384			if ctxErr := ctx.Err(); ctxErr != nil {
385				return nil, fmt.Errorf("read Nexus response: %w", ctxErr)
386			}
387			return nil, fmt.Errorf("read Nexus response: %w", err)
388		}
389		return body, nil
390	}
391	
392	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
393	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
394	func parseNexusURL(registryURL string) (host, repoName string, err error) {
395		raw := registryURL
396		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
397			raw = "https://" + raw
398		}
399		u, err := url.Parse(raw)
400		if err != nil {
401			return "", "", err
402		}
403		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
404		// Expected: ["repository", "<repoName>", ...]
405		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
406			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
407		}
408		host = u.Scheme + "://" + u.Host
409		repoName = parts[1]
410		return host, repoName, nil
411	}
412	
413	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
414	func cleanMemberAlias(name string) string {
415		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
416			if strings.HasSuffix(name, suffix) {
417				return name[:len(name)-len(suffix)]
418			}
419		}
420		return name
421	}

